/**
 * Rebuild the gitignored static data plane (public/books, public/covers) by
 * fetching it back from the PRODUCTION site, so a machine that has never run
 * the mirrors — a CI runner — can produce a deploy that carries every static
 * file production serves today. The id lists are frozen in
 * scripts/deploy-data-plane.json, generated by probing production (see the
 * "source" note in that file); text and covers are immutable, so bytes fetched
 * from the live site ARE the mirror bytes.
 *
 * Every listed file must fetch cleanly or this exits 1 — a Pages deploy
 * replaces the whole site, so "most of the covers" would silently delete the
 * rest from production. Covers have no R2 fallback door; nothing may be lost.
 *
 *   node scripts/fetch-data-plane.mjs            fetch whatever is missing
 *   BOOK_BASE=https://... overrides the source (default: production)
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync, statSync, renameSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const BASE = (process.env.BOOK_BASE || 'https://focus-reader-48z.pages.dev').replace(/\/+$/, '');
const plane = JSON.parse(readFileSync(path.join(ROOT, 'scripts', 'deploy-data-plane.json'), 'utf8'));

const jobs = [
    ...plane.books.map((id) => ({ url: `${BASE}/books/${id}.txt`, out: path.join(ROOT, 'public', 'books', `${id}.txt`), type: 'text/plain' })),
    ...plane.covers.map((id) => ({ url: `${BASE}/covers/${id}.webp`, out: path.join(ROOT, 'public', 'covers', `${id}.webp`), type: 'image' })),
];
mkdirSync(path.join(ROOT, 'public', 'books'), { recursive: true });
mkdirSync(path.join(ROOT, 'public', 'covers'), { recursive: true });

const failures = [];
let done = 0, skipped = 0;
async function fetchOne(job) {
    if (existsSync(job.out) && statSync(job.out).size > 0) { skipped++; return; }
    for (let attempt = 1; attempt <= 4; attempt++) {
        try {
            const res = await fetch(job.url, { redirect: 'follow' });
            const type = res.headers.get('content-type') || '';
            // The SPA fallback answers missing files with 200 text/html.
            if (!res.ok || !type.includes(job.type)) throw new Error(`HTTP ${res.status} ${type}`);
            const buf = Buffer.from(await res.arrayBuffer());
            if (!buf.length) throw new Error('empty body');
            const tmp = job.out + '.part';
            writeFileSync(tmp, buf);
            renameSync(tmp, job.out);
            return;
        } catch (err) {
            if (attempt === 4) { failures.push(`${job.url}: ${err.message}`); return; }
            await new Promise((r) => setTimeout(r, attempt * 1000));
        }
    }
}

const queue = [...jobs];
await Promise.all(Array.from({ length: 24 }, async () => {
    while (queue.length) {
        await fetchOne(queue.pop());
        if (++done % 500 === 0) console.log(`${done}/${jobs.length}`);
    }
}));

console.log(`fetched ${done - skipped}, already present ${skipped}, of ${jobs.length} (${plane.books.length} books, ${plane.covers.length} covers)`);
if (failures.length) {
    console.error(`\n${failures.length} FAILED — refusing a deploy that would drop production content:`);
    for (const f of failures.slice(0, 20)) console.error('  ' + f);
    process.exit(1);
}
